// ============================================================
// Fraud Model Drift Monitor — Power BI Power Query M Scripts
// Paste each query into Power BI Desktop > Transform Data > Advanced Editor
// Source files generated by notebook in artifacts/ folder
// ============================================================

// ---- Table: Drift Summary (one row per feature × scenario) --
let
    Source      = Csv.Document(File.Contents("../artifacts/drift_summary.csv"),
                      [Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]),
    promoted    = Table.PromoteHeaders(Source, [PromoteAllScalars=true]),
    typed       = Table.TransformColumnTypes(promoted, {
                      {"feature",           type text},
                      {"scenario",          type text},
                      {"psi_score",         type number},
                      {"wasserstein_dist",  type number},
                      {"ks_statistic",      type number},
                      {"ks_pvalue",         type number},
                      {"drift_detected",    type logical},
                      {"baseline_mean",     type number},
                      {"drift_mean",        type number},
                      {"baseline_std",      type number},
                      {"drift_std",         type number}
                  }),
    // severity band
    add_severity = Table.AddColumn(typed, "DriftSeverity",
                       each if [psi_score] >= 0.25 then "High"
                            else if [psi_score] >= 0.1 then "Medium"
                            else "Low",
                       type text),
    // percent shift in mean
    add_shift    = Table.AddColumn(add_severity, "MeanShiftPct",
                       each if [baseline_mean] <> 0
                            then ([drift_mean] - [baseline_mean]) / Number.Abs([baseline_mean]) * 100
                            else null,
                       type number)
in
    add_shift


// ---- Table: Predictions Timeline (model perf per batch) -----
let
    Source      = Csv.Document(File.Contents("../artifacts/predictions_timeline.csv"),
                      [Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]),
    promoted    = Table.PromoteHeaders(Source, [PromoteAllScalars=true]),
    typed       = Table.TransformColumnTypes(promoted, {
                      {"batch_date",           type date},
                      {"scenario",             type text},
                      {"fraud_rate_actual",    type number},
                      {"fraud_rate_predicted", type number},
                      {"precision",            type number},
                      {"recall",               type number},
                      {"f1",                   type number},
                      {"roc_auc",              type number},
                      {"total_transactions",   Int64.Type},
                      {"fraud_count",          Int64.Type}
                  }),
    add_month   = Table.AddColumn(typed,     "Month",      each Date.Month([batch_date]),   Int64.Type),
    add_year    = Table.AddColumn(add_month, "Year",       each Date.Year([batch_date]),    Int64.Type),
    add_yearmo  = Table.AddColumn(add_year,  "YearMonth",
                      each Text.From([Year]) & "-" & Text.PadStart(Text.From([Month]), 2, "0"),
                      type text),
    // flag rows where performance dropped below threshold
    add_alert   = Table.AddColumn(add_yearmo, "F1Alert",
                      each if [f1] < 0.75 then "Below Threshold" else "OK",
                      type text),
    sorted      = Table.Sort(add_alert, {{"batch_date", Order.Ascending}, {"scenario", Order.Ascending}})
in
    sorted


// ---- Table: Evidently Report Index -------------------------
let
    Source   = Csv.Document(File.Contents("../artifacts/evidently_reports_index.csv"),
                   [Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]),
    promoted = Table.PromoteHeaders(Source, [PromoteAllScalars=true]),
    typed    = Table.TransformColumnTypes(promoted, {
                   {"report_name",    type text},
                   {"scenario",       type text},
                   {"generated_at",   type datetime},
                   {"file_path",      type text},
                   {"num_features",   Int64.Type},
                   {"drifted_count",  Int64.Type}
               }),
    add_drift_pct = Table.AddColumn(typed, "DriftedFeaturePct",
                        each if [num_features] > 0
                             then [drifted_count] / [num_features] * 100
                             else null,
                        type number)
in
    add_drift_pct


// ---- Table: Dates (Calendar dimension) ----------------------
let
    start_date  = #date(2023, 1, 1),
    end_date    = #date(2024, 12, 31),
    day_count   = Duration.Days(end_date - start_date) + 1,
    date_list   = List.Dates(start_date, day_count, #duration(1, 0, 0, 0)),
    date_table  = Table.FromList(date_list, Splitter.SplitByNothing(), {"date"}),
    typed       = Table.TransformColumnTypes(date_table, {{"date", type date}}),
    add_year    = Table.AddColumn(typed,    "Year",       each Date.Year([date]),        Int64.Type),
    add_month   = Table.AddColumn(add_year, "Month",      each Date.Month([date]),       Int64.Type),
    add_mname   = Table.AddColumn(add_month,"MonthName",  each Date.MonthName([date]),   type text),
    add_qtr     = Table.AddColumn(add_mname,"Quarter",    each "Q" & Text.From(Date.QuarterOfYear([date])), type text),
    add_yearmo  = Table.AddColumn(add_qtr,  "YearMonth",
                      each Text.From([Year]) & "-" & Text.PadStart(Text.From([Month]), 2, "0"),
                      type text)
in
    add_yearmo
